import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  IconButton,
  Slide,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';
import { TransitionProps } from '@mui/material/transitions';
import { appColors } from '../../../../../theme/appColors';
import { IPurchaseJewelBasketItem } from '../../../../../core/Interface/purchaseJewellery.interface';
import { addItem, removeItem } from '../../../store/BasketSlice';
import { useAppDispatch } from '../../../../../store/hooks';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import DiamondOutlinedIcon from '@mui/icons-material/DiamondOutlined';
import FieldHeader from '../../../../../components/FieldHeader';

interface IJewelBasketItemEditModel {
  item: IPurchaseJewelBasketItem;
  open: boolean;
  handleClose: () => void;
}

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & { children: React.ReactElement<string, string> },
  ref: React.Ref<unknown>,
) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const toNum = (v: string | number) => {
  const n = parseFloat(String(v));
  return Number.isFinite(n) ? n : 0;
};

const JewelBasketItemEditModel: React.FC<IJewelBasketItemEditModel> = ({
  item,
  open,
  handleClose,
}) => {
  const dispatch = useAppDispatch();

  const [goldPrice8g, setGoldPrice8g] = React.useState<number>(item.unitPrice ?? 0);
  const [karatText, setKaratText] = React.useState<string>(item.goldKarat ?? '22K');
  const [weightG, setWeightG] = React.useState<string>(item.goldWeight?.toString() ?? '');

  const perGram = React.useMemo(() => (goldPrice8g > 0 ? goldPrice8g / 8 : 0), [goldPrice8g]);
  const weightValue = React.useMemo(() => toNum(weightG), [weightG]);
  const goldPriceForWeight = React.useMemo(() => perGram * weightValue, [perGram, weightValue]);
  const finalAmount = React.useMemo(() => {
    if (perGram <= 0 || weightValue <= 0) return null;
    return goldPriceForWeight;
  }, [perGram, weightValue, goldPriceForWeight]);

  const handleUpdate = () => {
    if (finalAmount === null) return;
    dispatch(addItem({
      ...item,
      unitPrice: goldPrice8g,
      goldKarat: karatText,
      goldWeight: weightValue,
      cost: finalAmount,
      total: finalAmount,
    }));
    handleClose();
  };

  const inputSx = {
    '& .MuiOutlinedInput-root': {
      backgroundColor: alpha(appColors.white, 0.92),
      borderRadius: '4px',
      '& fieldset': { borderColor: alpha(appColors.blueGreyishLight[80], 0.16) },
      '&:hover fieldset': { borderColor: alpha('#2563EB', 0.28) },
      '&.Mui-focused fieldset': { borderColor: '#2563EB' },
    },
  };

  return (
    <Dialog
      PaperProps={{
        sx: {
          background: 'linear-gradient(180deg, rgba(255,255,255,0.98) 0%, rgba(248,251,255,0.96) 100%)',
          border: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
          borderRadius: '8px',
          boxShadow: '0 30px 80px rgba(15,23,42,0.28)',
          maxWidth: 'calc(100vw - 32px)',
          overflow: 'hidden',
          width: 480,
        },
      }}
      TransitionComponent={Transition}
      fullWidth
      maxWidth={false}
      onClose={handleClose}
      open={open}
    >
      {/* Header */}
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background: 'linear-gradient(135deg, rgba(239,246,255,0.96) 0%, rgba(224,236,255,0.98) 54%, rgba(255,247,237,0.96) 100%)',
            borderBottom: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
            px: { xs: 2.5, md: 4 },
            py: { xs: 2.5, md: 3 },
          }}
        >
          <Box sx={{ alignItems: 'flex-start', display: 'flex', gap: 2, justifyContent: 'space-between' }}>
            <Stack direction="row" alignItems="center" spacing={1.5}>
              <DiamondOutlinedIcon sx={{ color: '#7c3aed', fontSize: 28 }} />
              <Box>
                <Typography sx={{ color: alpha(appColors.blueGreyishLight[80], 0.62), fontSize: '0.74rem', letterSpacing: '0.16em', textTransform: 'uppercase' }}>
                  Jewellery Item
                </Typography>
                <Typography sx={{ color: '#142352', fontSize: '1.2rem', fontWeight: 700, lineHeight: 1.2 }}>
                  {item.name}
                </Typography>
              </Box>
            </Stack>
            <IconButton
              onClick={handleClose}
              sx={{ backgroundColor: alpha(appColors.white, 0.72), border: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`, color: alpha(appColors.blueGreyishLight[80], 0.72), mr: -0.8, mt: -0.5 }}
            >
              <CloseRoundedIcon />
            </IconButton>
          </Box>
        </Box>
      </DialogTitle>

      {/* Content */}
      <DialogContent sx={{ p: 0 }}>
        <Box sx={{ px: { xs: 2.5, md: 4 }, py: { xs: 2.5, md: 3 } }}>
          <Box sx={{ mb: 2.5 }}>
            <FieldHeader title="Gold Price (8g)" />
            <TextField
              fullWidth
              size="small"
              sx={inputSx}
              type="number"
              inputProps={{ step: 'any' }}
              value={goldPrice8g}
              onChange={(e) => setGoldPrice8g(+e.target.value)}
            />
          </Box>

          <Box sx={{ mb: 2.5 }}>
            <FieldHeader title="Karat (purity)" />
            <TextField
              fullWidth
              size="small"
              sx={inputSx}
              value={karatText}
              onChange={(e) => setKaratText(e.target.value)}
            />
          </Box>

          <Box sx={{ mb: 2.5 }}>
            <FieldHeader title="Gold weight (g)" />
            <TextField
              fullWidth
              size="small"
              sx={inputSx}
              type="number"
              inputProps={{ step: 'any' }}
              value={weightG}
              onChange={(e) => setWeightG(e.target.value)}
            />
          </Box>

          {/* Live summary */}
          <Box
            sx={{
              background: alpha('#059669', 0.06),
              border: `1px solid ${alpha('#059669', 0.18)}`,
              borderRadius: '6px',
              p: 2,
            }}
          >
            <Box sx={{ display: 'flex', justifyContent: 'space-between', py: 0.5 }}>
              <Typography sx={{ color: alpha('#059669', 0.8), fontSize: 12, fontWeight: 600 }}>Gold Value</Typography>
              <Typography sx={{ color: '#065f46', fontSize: 13, fontWeight: 700 }}>{goldPriceForWeight.toFixed(2)}</Typography>
            </Box>
            <Divider sx={{ my: 1 }} />
            <Box sx={{ display: 'flex', justifyContent: 'space-between', py: 0.5 }}>
              <Typography sx={{ color: alpha('#059669', 0.8), fontSize: 12, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '1px' }}>Final Amount</Typography>
              <Typography sx={{ color: '#065f46', fontSize: 16, fontWeight: 900 }}>
                {finalAmount !== null ? finalAmount.toFixed(2) : '--'}
              </Typography>
            </Box>
          </Box>
        </Box>
      </DialogContent>

      {/* Footer */}
      <DialogActions sx={{ p: 0 }}>
        <Box
          sx={{
            alignItems: { xs: 'stretch', md: 'center' },
            backgroundColor: alpha('#F8FAFC', 0.94),
            borderTop: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.08)}`,
            display: 'flex',
            flexDirection: { xs: 'column', md: 'row' },
            gap: 2,
            justifyContent: 'space-between',
            px: { xs: 2.5, md: 4 },
            py: 2.3,
            width: '100%',
          }}
        >
          <Button
            onClick={() => { dispatch(removeItem(item.id)); handleClose(); }}
            startIcon={<DeleteOutlineIcon fontSize="small" />}
            sx={{ borderColor: alpha('#B42318', 0.4), borderRadius: '4px', color: '#B42318', fontWeight: 700, height: 46, px: 2.5, textTransform: 'none' }}
            variant="outlined"
          >
            Remove
          </Button>
          <Box sx={{ display: 'flex', gap: 1.5 }}>
            <Button
              onClick={handleClose}
              sx={{ borderColor: alpha('#142352', 0.22), borderRadius: '4px', color: '#142352', fontWeight: 700, height: 46, minWidth: 100, px: 3, textTransform: 'none' }}
              variant="outlined"
            >
              Cancel
            </Button>
            <Button
              disabled={finalAmount === null}
              onClick={handleUpdate}
              sx={{ background: 'linear-gradient(135deg, #2563EB 0%, #1D4ED8 100%)', borderRadius: '4px', boxShadow: '0 12px 24px rgba(37,99,235,0.22)', fontWeight: 700, height: 46, minWidth: 130, px: 3, textTransform: 'none', '&:hover': { background: 'linear-gradient(135deg, #1D4ED8 0%, #1E40AF 100%)' }, '&.Mui-disabled': { background: '#cbd5e1', boxShadow: 'none', color: '#64748b' } }}
              variant="contained"
            >
              Update Item
            </Button>
          </Box>
        </Box>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(JewelBasketItemEditModel);
