import {
  Box,
  Grid,
  IconButton,
  Paper,
  Skeleton,
  Stack,
  styled,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useEffect, useMemo, useState } from 'react';
import usePurchase from '../../usePurchase';
import { IProductData } from '../../../../core/Interface/product.interface';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import AddPurchase from '../AddPurchase';

const TILE_BG = 'linear-gradient(145deg, #eef2ff 0%, #e0e7ff 100%)';
const TILE_BG_HVR = 'linear-gradient(145deg, #dde5ff 0%, #c7d6ff 100%)';
const TILE_NAME = '#0F1D4D';
const TILE_PRICE = '#0F8B8D';
const TILE_BORDER = 'rgba(99, 120, 220, 0.18)';
const TILE_NAV = 'linear-gradient(135deg, #0F1D4D 0%, #1E3A8A 100%)';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const PRODUCT_MAX_COUNT_PER_ROW = 15;

const JewelProducts = ({
  selectCat,
  products,
}: {
  selectCat: string;
  products: IProductData[];
}) => {
  const { currencyCode, isLoading } = usePurchase();
  const [nextPage, setNextPage] = useState(0);
  const [openAddPurchase, setOpenAddPurchase] = React.useState(false);
  const [selectedProduct, setSelectedProduct] = React.useState<IProductData | null>(null);

  useEffect(() => {
    setNextPage(0);
  }, [selectCat]);

  const productPageWiseData = useMemo(() => {
    const totalRecords = products.length;
    const pageStaticVal = nextPage * PRODUCT_MAX_COUNT_PER_ROW;
    const sliceLastIndex = pageStaticVal + PRODUCT_MAX_COUNT_PER_ROW;
    return { catList: products.slice(pageStaticVal, sliceLastIndex), totalRecords, pageStaticVal };
  }, [nextPage, products]);

  const handleProductClick = (item: IProductData) => {
    setSelectedProduct(item);
    setOpenAddPurchase(true);
  };

  return (
    <Box sx={{ mt: '4px' }}>
      <Grid container spacing={1}>
        {!isLoading &&
          products &&
          productPageWiseData.catList.map((p) => (
            <Grid item key={p.id} md={1.5} sm={4} xs={4}>
              <Item
                onClick={() => handleProductClick(p)}
                sx={{
                  background: TILE_BG,
                  border: `1px solid ${TILE_BORDER}`,
                  boxShadow: 'none',
                  transition: 'background 0.15s, box-shadow 0.15s',
                  '&:hover': {
                    background: TILE_BG_HVR,
                    boxShadow: `0 3px 10px ${alpha('#0F1D4D', 0.12)}`,
                  },
                }}
              >
                <Stack alignItems="center" direction="column" sx={{ px: 0.5 }}>
                  <Typography
                    sx={{
                      color: TILE_NAME,
                      fontSize: 11,
                      fontWeight: 700,
                      lineHeight: 1.2,
                      mb: '2px',
                      textAlign: 'center',
                    }}
                  >
                    {p.name.length > 16 ? p.name.substring(0, 16) + '…' : p.name}
                  </Typography>
                  <Typography
                    sx={{
                      color: TILE_PRICE,
                      fontSize: 11,
                      fontVariantNumeric: 'tabular-nums',
                      fontWeight: 800,
                    }}
                  >
                    {currencyCode} {getPriceFormatWithoutCurrency(p.unitPrice)}
                  </Typography>
                </Stack>
              </Item>
            </Grid>
          ))}

        {/* Empty filler tiles */}
        {!isLoading &&
          PRODUCT_MAX_COUNT_PER_ROW > productPageWiseData.catList.length &&
          Array.from(Array(PRODUCT_MAX_COUNT_PER_ROW - productPageWiseData.catList.length).keys()).map((k) => (
            <Grid item key={k + '-jewel_not_product'} md={1.5} sm={4} xs={4}>
              <Item
                sx={{
                  background: '#eef2ff',
                  border: `1px solid ${TILE_BORDER}`,
                  boxShadow: 'none',
                  cursor: 'default',
                  opacity: 0.4,
                }}
              />
            </Grid>
          ))}

        {/* Pagination */}
        {!isLoading && (
          <Grid item key="jewel_arrow_product" md={1.5} sm={4} xs={4}>
            <Item sx={{ background: TILE_NAV, cursor: 'default' }}>
              <Grid container sx={{ cursor: 'pointer' }}>
                <Grid item sm={6}>
                  <IconButton
                    disabled={nextPage <= 0}
                    onClick={() => setNextPage((cur) => cur - 1)}
                    size="small"
                    sx={{ color: '#fff', '&:disabled': { color: 'rgba(255,255,255,0.25)' } }}
                  >
                    <ArrowBackIosNewIcon sx={{ fontSize: 22 }} />
                  </IconButton>
                </Grid>
                <Grid item sm={6}>
                  <IconButton
                    disabled={productPageWiseData.pageStaticVal + PRODUCT_MAX_COUNT_PER_ROW >= productPageWiseData.totalRecords}
                    onClick={() => setNextPage((cur) => cur + 1)}
                    size="small"
                    sx={{ color: '#fff', '&:disabled': { color: 'rgba(255,255,255,0.25)' } }}
                  >
                    <ArrowForwardIosIcon sx={{ fontSize: 22 }} />
                  </IconButton>
                </Grid>
              </Grid>
            </Item>
          </Grid>
        )}
      </Grid>

      {/* Loading skeletons */}
      {isLoading && (
        <Grid container spacing={1} sx={{ pt: 1 }}>
          {Array.from({ length: 16 }, (_, i) => i + 1).map((item) => (
            <Grid item key={'jewel_product_loading_' + item} md={1.5} sm={4} xs={4}>
              <Skeleton height={'var(--tile-h)'} sx={{ borderRadius: '10px' }} variant="rectangular" />
            </Grid>
          ))}
        </Grid>
      )}

      {openAddPurchase && selectedProduct && (
        <AddPurchase
          data={selectedProduct}
          handleCloseDialog={() => { setOpenAddPurchase(false); setSelectedProduct(null); }}
          openModel={openAddPurchase}
          title="Add Jewellery Item"
        />
      )}
    </Box>
  );
};

export default React.memo(JewelProducts);
