import { Box, Grid, Typography } from '@mui/material';
import React from 'react';
import JewelSupplierSearch from './SupplierSearch';
import { appColors, HEADER_GRADIENT } from '../../../../theme/appColors';
import JewelSummary from './Summary';
import JewelBasketItems from './BasketItems';

const colHeader = (label: string, align: 'left' | 'right' = 'right') => (
  <Typography
    align={align}
    sx={{
      textTransform: 'uppercase',
      fontWeight: 700,
      fontSize: 10,
      color: 'rgba(255,255,255,0.8)',
      letterSpacing: '0.5px',
    }}
  >
    {label}
  </Typography>
);

const PurchaseJewelleryLeft = () => {
  return (
    <Box
      sx={{
        position: 'fixed',
        left: 4,
        width: '32%',
        height: 'calc(100vh - 96px)',
        display: 'flex',
        flexDirection: 'column',
        zIndex: 10,
        borderRadius: '12px',
        overflow: 'hidden',
        boxShadow: '0 4px 24px rgba(0,20,137,0.14)',
        backgroundColor: appColors.white,
      }}
    >
      {/* Supplier search */}
      <Box
        sx={{
          p: '10px 10px 8px 10px',
          backgroundColor: appColors.white,
          borderBottom: `1px solid ${appColors.darkGray[10]}`,
        }}
      >
        <JewelSupplierSearch />
      </Box>

      {/* Column headers */}
      <Box sx={{ background: HEADER_GRADIENT, px: '12px', py: '8px' }}>
        <Grid container flexWrap="nowrap" spacing={1}>
          <Grid item md={3} xs={3}>{colHeader('Item', 'left')}</Grid>
          <Grid item md={2} xs={2}>{colHeader('Qty')}</Grid>
          <Grid item md={2} xs={2}>{colHeader('Karat')}</Grid>
          <Grid item md={3} xs={3}>{colHeader('Weight')}</Grid>
          <Grid item md={3} xs={3}>{colHeader('Total')}</Grid>
        </Grid>
      </Box>

      {/* Basket items — scrollable */}
      <Box
        sx={{
          flex: 1,
          overflowY: 'auto',
          backgroundColor: appColors.white,
          scrollbarWidth: 'thin',
          '&::-webkit-scrollbar': { width: '3px' },
          '&::-webkit-scrollbar-thumb': { backgroundColor: '#94a3b8', borderRadius: '2px' },
        }}
      >
        <JewelBasketItems />
      </Box>

      {/* Summary footer */}
      <JewelSummary />
    </Box>
  );
};

export default React.memo(PurchaseJewelleryLeft);
